#!/bin/bash
source /private/tmp/claude-501/-Users-kyle-Developer-grantiva-cli/b9f2e919-f7a5-4b94-a1bc-202f523560f4/scratchpad/cov3-android/env.sh
cd $P; ST="bash $S/tools/settings.sh emulator-5554"; LW=.maestro/coverage/18-long-wait.yaml
rec AND-066 "$ST; nohup $GRANTIVA run --device emulator-5554 --no-build --flow $LW > $E/AND-066/run.out 2> $E/AND-066/run.err & p=\$!; for i in \$(seq 1 60); do [ -f .grantiva/android-settings-emulator-5554.json ] && break; sleep 1; done; sleep 3; echo during:; $ST; cat .grantiva/android-settings-emulator-5554.json; echo; wait \$p; echo exit=\$?; echo after:; $ST; ls .grantiva/android-settings-*.json 2>&1"
rec AND-068 "nohup $GRANTIVA run --device emulator-5554 --no-build --flow $LW > $E/AND-068/run2.out 2> $E/AND-068/run2.err & p=\$!; for i in \$(seq 1 60); do [ -f .grantiva/android-settings-emulator-5554.json ] && break; sleep 1; done; sleep 3; kill -9 \$p; sleep 2; echo after-kill:; $ST; ls .grantiva/android-settings-*.json; RP=\$(ps -ax -o pid=,args= | grep '[g]rantiva-runner.*emulator-5554' | awk '{print \$1}'); echo orphan-runner=\$RP; for i in \$(seq 1 30); do [ -z \"\$(ps -ax -o pid=,args= | grep '[g]rantiva-runner.*emulator-5554')\" ] && break; sleep 2; done; echo runner-gone-after=\$((i*2))s; $GRANTIVA run --device emulator-5554 --no-build --flow .maestro/01-browse.yaml 2>&1 | grep -E 'Warning|restor|✓ 01-browse|Error'; echo after-next-run:; $ST; ls .grantiva/android-settings-*.json 2>&1"
rec AND-145 "nohup $GRANTIVA run --allow-device-settings --emulator cov3-android --no-build --flow $LW > $E/AND-145/run2.out 2> $E/AND-145/run2.err & p=\$!; for i in \$(seq 1 60); do [ -f .grantiva/android-settings-emulator-5554.json ] && break; sleep 1; done; sleep 3; echo during:; $ST; wait \$p; echo exit=\$?; echo after:; $ST"
echo G9B-DONE
